import{_ as t,o,c as a,a2 as s}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"Vue (Sight)","description":"","frontmatter":{"title":"Vue (Sight)"},"headers":[],"relativePath":"en/reference/vue.md","filePath":"en/reference/vue.md"}'),d={name:"en/reference/vue.md"};function i(r,e,n,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="vue-sight-seeing-the-screen" tabindex="-1">Vue (Sight): seeing the screen <a class="header-anchor" href="#vue-sight-seeing-the-screen" aria-label="Permalink to &quot;Vue (Sight): seeing the screen&quot;">​</a></h1><p>Vue is the screen perception organ. It captures, converts coordinates, locates visible text and remembers the topology of your displays. All its tools are read-only and are not subject to the Mains (Hands) ceiling. Vue does <strong>not</strong> read the screen for you: it returns images and positions, and it is up to the model to interpret them.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Role</th><th>Level</th></tr></thead><tbody><tr><td><a href="#vue-displays"><code>vue_displays</code></a></td><td>List the active displays</td><td>read</td></tr><tr><td><a href="#vue-snapshot"><code>vue_snapshot</code></a></td><td>Capture a display (PNG image and coordinate contract)</td><td>read</td></tr><tr><td><a href="#vue-resolve"><code>vue_resolve</code></a></td><td>Convert between image pixel and global point, without capturing</td><td>read</td></tr><tr><td><a href="#vue-find"><code>vue_find</code></a></td><td>Locate a visible label by OCR</td><td>read</td></tr><tr><td><a href="#vue-calibrate"><code>vue_calibrate</code></a></td><td>Save the display topology under a name</td><td>read</td></tr><tr><td><a href="#vue-profile"><code>vue_profile</code></a></td><td>Read the profile matched to the current environment</td><td>read</td></tr><tr><td><a href="#vue-profile-brief"><code>vue_profile_brief</code></a></td><td>Bootstrap brief for a sub-agent</td><td>read</td></tr><tr><td><a href="#vue-pilot-brief"><code>vue_pilot_brief</code></a></td><td>Per-task delegation package</td><td>read</td></tr></tbody></table><h2 id="erreurs-communes" tabindex="-1">Common errors <a class="header-anchor" href="#erreurs-communes" aria-label="Permalink to &quot;Common errors {#erreurs-communes}&quot;">​</a></h2><p>A Vue error never crashes the server: it comes back in the form <code>{&quot;error&quot;: &quot;&lt;code&gt;&quot;, &quot;message&quot;: &quot;&lt;detail&gt;&quot;}</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>permission_denied</code></td><td>A system permission is missing (Screen Recording)</td></tr><tr><td><code>invalid_arguments</code></td><td>An argument is invalid</td></tr><tr><td><code>index_out_of_range</code></td><td>The <code>display</code> index does not exist</td></tr><tr><td><code>capture_failed</code></td><td>The capture failed</td></tr><tr><td><code>exclusions_unreadable</code></td><td>The exclusions file is broken; the message names the file and the line, never the faulty value</td></tr></tbody></table><p>If in doubt about a permission, call <a href="./diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> first.</p><h2 id="vue-displays" tabindex="-1">vue_displays <a class="header-anchor" href="#vue-displays" aria-label="Permalink to &quot;vue_displays {#vue-displays}&quot;">​</a></h2><p>Lists all active displays. This is the starting point: the <code>index</code> returned is the value to pass as <code>display</code> to the other tools.</p><p><strong>Parameters</strong>: none.</p><p><strong>Returns</strong>: a list of objects <code>{index, width, height, is_main, origin: {x, y}, dpi}</code>.</p><p><strong>Example call</strong>: <code>vue_displays</code> with no arguments.</p><p><strong>Pitfalls</strong>: the origin of a secondary display can be negative in the global desktop.</p><h2 id="vue-snapshot" tabindex="-1">vue_snapshot <a class="header-anchor" href="#vue-snapshot" aria-label="Permalink to &quot;vue_snapshot {#vue-snapshot}&quot;">​</a></h2><p>Captures a display and returns it as an image, after censoring and redaction.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>display</code></td><td>integer</td><td><code>0</code></td><td>no</td><td>Display index, as listed by <code>vue_displays</code></td></tr><tr><td><code>max_width</code></td><td>integer</td><td><code>720</code></td><td>no</td><td>Downscaling cap for the served image, in image pixels; <code>0</code> disables it</td></tr><tr><td><code>region</code></td><td>object <code>{x, y, width, height}</code></td><td>whole display</td><td>no</td><td>Sub-region to capture, in points, local to the display, clamped to the display</td></tr></tbody></table><p><strong>Level</strong>: read.</p><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;display&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1440</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;region&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">800</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">600</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p><strong>Returns</strong>: <strong>two content blocks, in this order</strong>: (1) a text block containing the <code>coord_space</code> JSON contract, (2) a base64 PNG image block (<code>image/png</code>). All of <code>coord_space</code> is expressed in points, the unit in which <code>main_click</code> acts; <code>image_scale</code> is the number of image pixels served <strong>per point</strong>. <code>coord_space.region</code> reports what was actually captured, and <code>coord_space.secret_rects_available</code> says whether masking by secret field could run.</p><p><strong>Censoring.</strong> The windows of the applications you protect (<code>apps</code>, <code>secret_apps</code> of the exclusions) are never refused: they are <strong>censored</strong>, replaced by an opaque flat tint <code>#3A2A5C</code>, like the declared zones and the secret fields; the rest of the screen is served. When a rule exists, the text block also carries:</p><table tabindex="0"><thead><tr><th>Field</th><th>Values</th><th>Meaning</th></tr></thead><tbody><tr><td><code>censored</code></td><td>boolean</td><td>A censoring was applied</td></tr><tr><td><code>censored_reason</code></td><td><code>none</code>, <code>zones</code>, <code>unstable</code>, <code>unknown</code></td><td>Reason</td></tr><tr><td><code>censored_rects</code></td><td>list of <code>{x, y, width, height}</code></td><td>Censored zones, in global points, clipped to the capture</td></tr></tbody></table><p><strong>Errors</strong>: see <a href="#erreurs-communes">Common errors</a>.</p><p><strong>Pitfalls</strong></p><ul><li>A <code>#3A2A5C</code> zone is masked content, not an empty screen.</li><li>With <code>unstable</code> or <code>unknown</code>, the protected windows could not be placed, even after an automatic new capture: the <strong>whole</strong> image is the flat tint. Try again.</li><li>On macOS, the menu bar is also censored as long as a protected application is in the foreground.</li><li>The default value of <code>max_width</code> is 720: ask for more for fine detail.</li><li>On Windows, a point is a physical pixel of the virtual screen and <code>backing_scale</code> is always 1.0.</li><li>Daimon does not interpret the image: look at it yourself.</li></ul><h2 id="vue-resolve" tabindex="-1">vue_resolve <a class="header-anchor" href="#vue-resolve" aria-label="Permalink to &quot;vue_resolve {#vue-resolve}&quot;">​</a></h2><p>Converts an image pixel (seen in a <code>vue_snapshot</code> of <code>display</code>) to a global point, and vice versa, <strong>without capturing</strong>. Use it rather than computing offset and scale yourself: a resolved pair is directly clickable.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>display</code></td><td>integer</td><td><code>0</code></td><td>no</td><td>Display index</td></tr><tr><td><code>max_width</code></td><td>integer</td><td><code>720</code></td><td>no</td><td>The same cap as the original snapshot; <code>0</code> disables it</td></tr><tr><td><code>region</code></td><td>object <code>{x, y, width, height}</code></td><td>whole display</td><td>no</td><td>The same region as the snapshot, in points, local to the display</td></tr><tr><td><code>image_x</code>, <code>image_y</code></td><td>number</td><td>none</td><td>no</td><td>Image pixel to convert (both together)</td></tr><tr><td><code>global_x</code>, <code>global_y</code></td><td>number</td><td>none</td><td>no</td><td>Global point to convert to an image pixel (both together)</td></tr><tr><td><code>source</code></td><td>string</td><td><code>&quot;probe&quot;</code></td><td>no</td><td><code>&quot;probe&quot;</code> reads the live display geometry; <code>&quot;profile&quot;</code> reads the matched calibration profile, falling back to <code>probe</code> if none matches</td></tr></tbody></table><p><strong>Level</strong>: read.</p><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;display&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">720</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;image_x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">360</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;image_y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Returns</strong>: <code>{global_x, global_y}</code> if you pass <code>image_x</code>/<code>image_y</code>, <code>{image_x, image_y}</code> if you pass <code>global_x</code>/<code>global_y</code>.</p><p><strong>Errors</strong>: see <a href="#erreurs-communes">Common errors</a>.</p><p><strong>Pitfalls</strong>: <code>max_width</code> and <code>region</code> must be identical to those of the snapshot, otherwise the conversion is wrong.</p><h2 id="vue-find" tabindex="-1">vue_find <a class="header-anchor" href="#vue-find" aria-label="Permalink to &quot;vue_find {#vue-find}&quot;">​</a></h2><p>Vue&#39;s fallback: locates a <strong>visible</strong> label by on-device OCR and returns clickable global coordinates, in points. Useful when <code>touche_tree</code> and <code>touche_probe</code> stay silent (old Win32 applications, custom-drawn ones, Electron) and there is therefore no accessibility tree to click.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>text</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Text to locate on the screen</td></tr><tr><td><code>display</code></td><td>integer</td><td><code>0</code></td><td>no</td><td>Display index</td></tr><tr><td><code>max_width</code></td><td>integer</td><td><code>720</code></td><td>no</td><td>Downscaling cap for the internal capture; <code>0</code> disables it</td></tr><tr><td><code>region</code></td><td>object <code>{x, y, width, height}</code></td><td>whole display</td><td>no</td><td>Search sub-region, in points, local to the display</td></tr><tr><td><code>min_score</code></td><td>number</td><td><code>0.6</code></td><td>no</td><td>Minimum score, in <code>[0, 1]</code>, to count as a hit</td></tr><tr><td><code>source</code></td><td>string</td><td><code>&quot;probe&quot;</code></td><td>no</td><td><code>&quot;probe&quot;</code> or <code>&quot;profile&quot;</code>, as for <code>vue_resolve</code></td></tr></tbody></table><p><strong>Level</strong>: read.</p><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Enregistrer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;display&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;min_score&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Returns</strong>: <code>{found, text, score, image_x, image_y, global_x, global_y, candidates}</code>. On failure, <code>candidates</code> contains the 5 closest visible labels. Pass <code>global_x</code> and <code>global_y</code> as is to <code>main_click</code> (default <code>global</code> space).</p><p><strong>Errors</strong>: see <a href="#erreurs-communes">Common errors</a>. On Windows, a missing OCR language is reported as an error, never as an empty failure.</p><p><strong>Pitfalls</strong></p><ul><li>The engine is the system&#39;s: Apple Vision on a macOS build compiled with <code>--features apple-vision</code>, <code>Windows.Media.Ocr</code> on Windows. Any other build embeds the dummy <code>FakeOcr</code> engine: no real recognition, always a failure.</li><li>The OCR reads the <strong>censored</strong> image: no word touching a censored zone is returned. With an exclusion rule, the response adds <code>censored</code> and <code>censored_reason</code>.</li><li>It is a locator, not an interpreter: it returns a position.</li></ul><h2 id="vue-calibrate" tabindex="-1">vue_calibrate <a class="header-anchor" href="#vue-calibrate" aria-label="Permalink to &quot;vue_calibrate {#vue-calibrate}&quot;">​</a></h2><p>Freezes the current display topology under a name (idempotent write: same name, update) and returns the saved profile. A profile lets <code>vue_resolve</code> and <code>vue_find</code> use <code>source=&quot;profile&quot;</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Profile name</td></tr></tbody></table><p><strong>Level</strong>: read (the tool saves a calibration profile, it does not act on the screen).</p><p><strong>Example call</strong>: <code>{ &quot;name&quot;: &quot;bureau-deux-ecrans&quot; }</code></p><p><strong>Returns</strong>: the saved profile.</p><h2 id="vue-profile" tabindex="-1">vue_profile <a class="header-anchor" href="#vue-profile" aria-label="Permalink to &quot;vue_profile {#vue-profile}&quot;">​</a></h2><p>Indicates the calibration profile matched to the current display topology, or reports an unknown environment along with the known profile names.</p><p><strong>Parameters</strong>: none. <strong>Level</strong>: read.</p><h2 id="vue-profile-brief" tabindex="-1">vue_profile_brief <a class="header-anchor" href="#vue-profile-brief" aria-label="Permalink to &quot;vue_profile_brief {#vue-profile-brief}&quot;">​</a></h2><p>Produces the bootstrap brief of a delegated sub-agent: profile matching gate and addressable display indices.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>expected</code></td><td>string</td><td>none</td><td>no</td><td>Profile name to check</td></tr></tbody></table><p><strong>Level</strong>: read. <strong>Example call</strong>: <code>{ &quot;expected&quot;: &quot;bureau-deux-ecrans&quot; }</code></p><h2 id="vue-pilot-brief" tabindex="-1">vue_pilot_brief <a class="header-anchor" href="#vue-pilot-brief" aria-label="Permalink to &quot;vue_pilot_brief {#vue-pilot-brief}&quot;">​</a></h2><p>Produces the delegation package of a task: a go/no-go gate and a ready-to-paste prompt for a sub-agent, for the given objective. No AI call is made.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>objective</code></td><td>string</td><td>none</td><td><strong>yes</strong></td><td>Objective of the delegated task</td></tr><tr><td><code>expected</code></td><td>string</td><td>none</td><td>no</td><td>Expected profile name</td></tr></tbody></table><p><strong>Level</strong>: read.</p><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;objective&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Relever le numéro de version affiché dans la fenêtre À propos&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;expected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bureau-deux-ecrans&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Pitfalls</strong>: if the gate is not ready, calibrate first (<code>vue_calibrate</code>) rather than driving blind.</p>',64)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
